<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$id=(int)($_GET['id']??0);$s=$db->prepare('SELECT p.*,c.name client_name,c.company FROM client_projects p JOIN clients c ON c.id=p.client_id WHERE p.id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('Project not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){$type=(string)($_POST['type']??'');if($type==='milestone'){ $q=$db->prepare('INSERT INTO project_milestones(project_id,name,description,due_date,sort_order) VALUES(?,?,?,?,?)');$q->execute([$id,trim($_POST['name']),trim($_POST['description']),$_POST['due_date']?:null,(int)$_POST['sort_order']]); }elseif($type==='task'){ $q=$db->prepare('INSERT INTO project_tasks(project_id,milestone_id,title,description,due_date,priority) VALUES(?,?,?,?,?,?)');$q->execute([$id,(int)($_POST['milestone_id']?:0)?:null,trim($_POST['title']),trim($_POST['task_description']),$_POST['task_due_date']?:null,$_POST['priority']]);}elseif($type==='status'){ $new=$_POST['status'];$allowed=['planning','in_progress','on_hold','in_review','completed','cancelled'];if(in_array($new,$allowed,true)&&$new!==$p['status']){$db->beginTransaction();$db->prepare('UPDATE client_projects SET status=?,completed_at=CASE WHEN ?="completed" THEN NOW() ELSE completed_at END WHERE id=?')->execute([$new,$new,$id]);$db->prepare('INSERT INTO project_status_history(project_id,old_status,new_status,notes) VALUES(?,?,?,?)')->execute([$id,$p['status'],$new,trim($_POST['status_notes'])]);$db->commit();}}header('Location: project-delivery.php?id='.$id);exit;}$m=$db->prepare('SELECT * FROM project_milestones WHERE project_id=? ORDER BY sort_order,id');$m->execute([$id]);$milestones=$m->fetchAll();$t=$db->prepare('SELECT t.*,m.name milestone_name FROM project_tasks t LEFT JOIN project_milestones m ON m.id=t.milestone_id WHERE t.project_id=? ORDER BY t.due_date IS NULL,t.due_date,t.id');$t->execute([$id]);$tasks=$t->fetchAll();$total=count($tasks);$done=0;foreach($tasks as $x)if($x['status']==='completed')$done++;$progress=$total?round($done/$total*100):0;?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Project Delivery</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5"><div class="d-flex justify-content-between"><div><h1><?=$e($p['name'])?></h1><p class="text-muted"><?=$e($p['project_number'])?> · <?=$e($p['client_name'])?></p></div><span class="badge text-bg-dark align-self-start"><?=$e(str_replace('_',' ',$p['status']))?></span></div><div class="card mb-4"><div class="card-body"><div class="d-flex justify-content-between"><strong>Task Progress</strong><strong><?=$progress?>%</strong></div><div class="progress mt-2"><div class="progress-bar" style="width:<?=$progress?>%"></div></div></div></div><div class="row g-4"><div class="col-lg-5"><div class="card mb-4"><div class="card-body"><h2 class="h5">Change Status</h2><form method="post"><input type="hidden" name="type" value="status"><select class="form-select mb-2" name="status"><?php foreach(['planning','in_progress','on_hold','in_review','completed','cancelled'] as $st):?><option value="<?=$st?>" <?=$p['status']===$st?'selected':''?>><?=$e(str_replace('_',' ',$st))?></option><?php endforeach;?></select><textarea class="form-control mb-2" name="status_notes" placeholder="Status notes"></textarea><button class="btn btn-dark">Update</button></form></div></div><div class="card"><div class="card-body"><h2 class="h5">Add Milestone</h2><form method="post"><input type="hidden" name="type" value="milestone"><input class="form-control mb-2" name="name" placeholder="Milestone name" required><textarea class="form-control mb-2" name="description" placeholder="Description"></textarea><input class="form-control mb-2" type="date" name="due_date"><input class="form-control mb-2" type="number" name="sort_order" value="0"><button class="btn btn-dark">Add Milestone</button></form></div></div></div><div class="col-lg-7"><div class="card mb-4"><div class="card-body"><h2 class="h5">Add Task</h2><form method="post" class="row g-2"><input type="hidden" name="type" value="task"><div class="col-md-7"><input class="form-control" name="title" placeholder="Task title" required></div><div class="col-md-5"><select class="form-select" name="milestone_id"><option value="">No milestone</option><?php foreach($milestones as $x):?><option value="<?=$x['id']?>"><?=$e($x['name'])?></option><?php endforeach;?></select></div><div class="col-12"><textarea class="form-control" name="task_description" placeholder="Task description"></textarea></div><div class="col-md-4"><input class="form-control" type="date" name="task_due_date"></div><div class="col-md-4"><select class="form-select" name="priority"><option>normal</option><option>low</option><option>high</option><option>urgent</option></select></div><div class="col-md-4"><button class="btn btn-dark w-100">Add Task</button></div></form></div></div><div class="card"><div class="card-body"><h2 class="h5">Tasks</h2><?php foreach($tasks as $x):?><div class="border-bottom py-2"><strong><?=$e($x['title'])?></strong><div class="small text-muted"><?=$e($x['milestone_name']?:'Unassigned')?> · <?=$e($x['priority'])?> · <?=$e($x['status'])?> · Due <?=$e($x['due_date']?:'—')?></div></div><?php endforeach;if(!$tasks):?><p class="text-muted">No tasks yet.</p><?php endif;?></div></div></div></div></main></body></html>